    Xây dựng một lệnh để xem tệp dựa trên mime_type và thực thi nó.

    Cài đặt này bao gồm một kiểm tra để ngăn chặn việc nối lệnh bằng cách chặn 
    dấu chấm phẩy.
    '''
    # Kiểm tra tham số
    if len(sys.argv)!= 3:
        print("Usage: mailcap_find_match.py mime_type filename")
        sys.exit(1)

    # Lấy tham số
    mime_type = sys.argv[1]
    filename = sys.argv[2]

    # Tìm kiếm mã mailcap
    mailcap_path = os.getenv("MAILCAP")
    if mailcap_path is None:
        print("MAILCAP is not set")
        sys.exit(1)

    # Mở file mailcap
    try:
        mailcap_file = open(mailcap_path, "r")
    except IOError:
        print("Cannot open mailcap file")
        sys.exit(1)

    # Tìm kiếm mã mailcap
    for line in mailcap_file:
